const double sign = (n % 2 == 0) ? 1.0 : -1.0;
const double factorial_ratio = std::sqrt(boost::math::factorial<double>(n) /
                                         boost::math::factorial<double>(n + k));
const double exp_term = std::exp(-2.0 * r * r);
const double power_term = std::pow(2.0 * r, k);
const double laguerre_term = boost::math::laguerre_l(n, k)(4.0 * r * r);

return (sign / M_PI) * std::sqrt(factorial_ratio) * exp_term * power_term * laguerre_term;

